def smallest_lexicographical_subsequence(S, K):
    stack = []
    for char in S:
        while stack and stack[-1] > char and len(stack) - 1 + len(S) - S.index(stack[-1]) >= K:
            stack.pop()
        if len(stack) < K:
            stack.append(char)
    return ''.join(stack)

